parameters.jsCode:
let raw = ($json.output ?? '').trim();
if (raw.startsWith('```')) raw = raw.replace(/^```json\s*/i,'').replace(/^```\s*/i,'').replace(/\s*```$/,'');
let k = {}; try { k = JSON.parse(raw); } catch (e) { k = { response: raw }; }
return [{ json: { ok: true, intent: 'knowledge', reply_to_user: k.response || '', needs_user_reply: false } }];

const av = $json ?? {};
const core = $('Output IA → JSON').item.json;
const tz = core.tenant_timezone || 'Europe/Madrid';
const allSlots = Array.isArray(av.slots) ? av.slots : [];

const RANGES  = { manana:[6,14], mediodia:[13,16], tarde:[14,21], noche:[21,24] };
const DPNAME  = { manana:'por la mañana', mediodia:'a mediodía', tarde:'por la tarde', noche:'por la noche' };
const dp = (core.daypart || '').toString().normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().trim();
const range = RANGES[dp] || null;
const fmt = s => DateTime.fromISO(s.start_at).setZone(tz).toFormat('HH:mm');
const fecha = DateTime.fromISO(av.date).setZone(tz).setLocale('es').toFormat("cccc d 'de' LLLL");

let slots = allSlots, franja_vacia = false;
if (range) {
  slots = allSlots.filter(s => { const h = DateTime.fromISO(s.start_at).setZone(tz).hour; return h >= range[0] && h < range[1]; });
  franja_vacia = allSlots.length > 0 && slots.length === 0;
}
const franjaTxt = DPNAME[dp] || '';
const enFranja = slots.map(fmt).join(', ');
const diaCompleto = allSlots.map(fmt).join(', ');

let borrador;
if (slots.length) {
  borrador = `El ${fecha}${franjaTxt ? ' ' + franjaTxt : ''} hay estos huecos: ${enFranja}. ¿Cuál te encaja mejor?`;
} else if (franja_vacia) {
  borrador = `El ${fecha} ${franjaTxt} no queda ningún hueco, pero ese mismo día hay disponibilidad en otro momento: ${diaCompleto}. ¿Te viene bien alguno?`;
} else {
  borrador = `El ${fecha} no queda ningún hueco. ¿Quieres que mire otro día?`;
}
return [{ json: { date: av.date, fecha_humana: fecha, available: slots.length > 0,
  daypart: dp || null, franja_vacia, borrador } }];

const r = $json ?? {};
if (r.status === 'multiple') {
  const nombres = (r.candidates || []).map(c => c.name).join(', ');
  return [{ json: { ok: true, intent: 'list_availability', needs_user_reply: true,
    reply_to_user: `¿Para qué servicio? Tenemos: ${nombres}.` } }];
}
return [{ json: { ok: true, intent: 'list_availability', needs_user_reply: true,
  reply_to_user: 'No encuentro ese servicio. ¿Puedes decírmelo de otra forma?' } }];

const core = $('Output IA → JSON').item.json;
const svc = $json;  // salida de Resolve Service (single)
const tz = core.tenant_timezone || 'Europe/Madrid';
if (!core.date || !core.time) {
  return [{ json: { _incompleto: true, _reason: 'datetime', service_id: svc.service_id } }];
}
// Si es EXACTAMENTE el hueco que acaba de fallar, no volvemos a llamar al Booking API:
// el usuario quiere ver alternativas, no reintentar lo imposible.
if (core.offered_alt_slots === true
    && core.offered_alt_slots_date && core.offered_alt_slots_time
    && core.date === core.offered_alt_slots_date
    && core.time === core.offered_alt_slots_time) {
  return [{ json: { _slot_ya_fallido: true, service_id: svc.service_id } }];
}
const start = DateTime.fromISO(`${core.date}T${core.time}`, { zone: tz });
if (!start.isValid) return [{ json: { _incompleto: true, _reason: 'datetime', service_id: svc.service_id } }];
const phone = (core.contact && core.contact.phone) ? core.contact.phone : null;
const name  = (core.contact && core.contact.name)  ? core.contact.name  : null;
if (!phone && !name) {
  return [{ json: { _incompleto: true, _reason: 'contact', service_id: svc.service_id } }];
}
return [{ json: {
  service_id: svc.service_id,
  start_at: start.toISO(),
  contact_id: null,
  phone, query: name,
  source: 'ai',
  idempotency_key: `${core.sessionID || core.canal || 'lucia'}-${start.toISO()}`,
} }];

const r = $json ?? {};
const core = $('Output IA → JSON').item.json;
if (r.ok === true) {
  const a = r.data?.appointment || {};
  const tz = $('Output IA → JSON').item.json.tenant_timezone || 'Europe/Madrid';
  const cuando = a.start_at
    ? DateTime.fromISO(a.start_at).setZone(tz).setLocale('es').toFormat("cccc d 'de' LLLL 'a las' HH:mm")
    : '';
  return [{ json: { ok: true, intent: 'create_appointment', needs_user_reply: false,
    reply_to_user: (r.message && r.message.includes('idempotente'))
      ? `Tu cita ya estaba reservada para el ${cuando}.`
      : `Listo, cita confirmada para el ${cuando}.`,
    appointment: a, last_appointment_id: a.id } }];
}
const _errs = (r.data && Array.isArray(r.data.errors)) ? r.data.errors.join(' ') : (r.message || '');
if (r.status === 'validation_error' && /contact_id|phone|email|query|identificar al contacto/i.test(_errs)) {
  return [{ json: { ok: false, intent: 'create_appointment', needs_user_reply: true,
    reply_to_user: 'Para cerrar la cita necesito tu nombre y un teléfono de contacto. ¿Me los das?' } }];
}
if (r.status === 'slot_taken') {
  return [{ json: { ok: false, intent: 'create_appointment', needs_user_reply: true,
    reply_to_user: 'Ese horario acaba de ocuparse. ¿Quieres que mire otros huecos de ese día?',
    awaiting_slots_offer: true, alt_slots_date: core.date || null, alt_slots_time: core.time || null } }];
}
if (r.status === 'slot_conflict') {
  return [{ json: { ok: false, intent: 'create_appointment', needs_user_reply: true,
    reply_to_user: 'Ese horario no está disponible ese día. ¿Quieres que te diga los huecos libres?',
    awaiting_slots_offer: true, alt_slots_date: core.date || null, alt_slots_time: core.time || null } }];
}
return [{ json: { ok: false, intent: 'create_appointment', needs_user_reply: true,
  reply_to_user: r.message || 'No he podido crear la cita. ¿Lo intentamos de otra forma?' } }];

const r = $json ?? {};
if (r._reason === 'contact') return [{ json: { ok: true, intent: 'create_appointment', needs_user_reply: true,
  reply_to_user: 'Para cerrar la cita necesito tu nombre y un teléfono de contacto. ¿Me los das?' } }];
if (r._reason === 'datetime' || r._no_datetime) return [{ json: { ok: true, intent: 'create_appointment', needs_user_reply: true,
  reply_to_user: '¿Qué día y a qué hora te viene bien?' } }];
if (r.status === 'multiple') {
  const nombres = (r.candidates || []).map(c => c.name).join(', ');
  return [{ json: { ok: true, intent: 'create_appointment', needs_user_reply: true,
    reply_to_user: `¿Para qué servicio? Tenemos: ${nombres}.` } }];
}
return [{ json: { ok: true, intent: 'create_appointment', needs_user_reply: true,
  reply_to_user: 'No encuentro ese servicio. ¿Puedes decírmelo de otra forma?' } }];

const r = $json ?? {};
const failed = r.ok === false || Array.isArray(r.errors) || !!r.error;
if (failed) {
  const errs = Array.isArray(r.errors) ? r.errors.join(' ') : (r.message || r.error || '');
  const needsContact = /contact_id|phone|email|query|identificar al contacto/i.test(errs);
  return [{ json: {
    ok: false, intent: 'create_task', needs_user_reply: true,
    reply_to_user: needsContact
      ? '¿Me dices tu nombre y teléfono para dejar la nota?'
      : 'No he podido anotar la tarea. ¿Lo intentamos de otra forma?',
  } }];
}
return [{ json: { ok: true, intent: 'create_task', needs_user_reply: false,
  reply_to_user: 'Anotado, me encargo de ello.', task: r.data ?? r } }];

const c = $json ?? {};
const intent = (c.intent === 'null' || c.intent === undefined) ? null : (c.intent ?? null);
let reply = (c.reply_to_user || '').toString().trim();
let needs = c.needs_user_reply === true;
if (!reply) {
  // El Core no redactó nada: preguntamos por lo que falte según el flujo.
  if (intent === 'create_appointment') {
    if (!c.service_query) reply = '¿Para qué servicio quieres la cita?';
    else if (!c.date) reply = '¿Qué día te viene bien?';
    else if (!c.time) reply = '¿A qué hora en concreto?';
    else reply = '¿Me dices tu nombre y teléfono para la reserva?';
  } else if (intent === 'list_availability') {
    reply = '¿Qué día quieres que mire?';
  } else if (intent === 'reschedule_appointment' || intent === 'cancel_appointment') {
    reply = '¿De qué cita se trata? Dime el día y la hora.';
  } else if (intent === 'create_task') {
    reply = '¿Qué necesitas exactamente?';
  } else {
    reply = 'Hola, ¿en qué puedo ayudarte?';
  }
  needs = true;
}
return [{ json: { ok: true, intent, needs_user_reply: needs, reply_to_user: reply } }];

const core = $('Output IA → JSON').item.json;
const res = $json ?? {};
const tz = core.tenant_timezone || 'Europe/Madrid';
const phone = core.contact && core.contact.phone ? core.contact.phone : null;
const query = core.contact && core.contact.name ? core.contact.name : null;
const base = { intent: core.intent, phone, query };

if (!res.ok) {
  return [{ json: { ...base, _found: false, _reason: res.status === 'multiple' ? 'varios_contactos' : 'sin_contacto' } }];
}
const appts = Array.isArray(res.data && res.data.appointments) ? res.data.appointments : [];
if (!appts.length) return [{ json: { ...base, _found: false, _reason: 'sin_citas' } }];

const norm = s => (s || '').toString().normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLowerCase();
const msg = norm(core.message);
// "todas"/"ambas"/"las dos"(="the two of them")... es una petición EN BLOQUE. Se calcula
// ANTES de leer hora/ordinal para que "las dos" no se confunda con el ordinal "segunda" ni con
// una hora, y para que tampoco dispare el tie-break de 'última cita tocada'.
const bulk = /\b(todas|todos|ambas|ambos)\b/.test(msg) || /\b(las|los) dos\b/.test(msg);
const when = a => DateTime.fromISO(a.start_at).setZone(tz);
let cands = appts.slice();

// 1) appointment_date exacta del Core
const ad = core.appointment_date || null;
if (ad) { const f = cands.filter(a => when(a).toISODate() === ad); if (f.length) cands = f; }

// 2) día de la semana en el mensaje
const WD = { domingo: 7, lunes: 1, martes: 2, miercoles: 3, jueves: 4, viernes: 5, sabado: 6 };
for (const [name, iso] of Object.entries(WD)) {
  if (cands.length > 1 && msg.includes(name)) {
    const f = cands.filter(a => when(a).weekday === iso);
    if (f.length) { cands = f; break; }
  }
}

// 3) hora: appointment_time del Core, o "HH:MM" / "a las HH" en el mensaje
let hm = core.appointment_time || null;
if (!hm) {
  const m = msg.match(/\b(\d{1,2})[:h.](\d{2})\b/) || msg.match(/\b(?:a\s+)?las\s+(\d{1,2})\b/);
  if (m) hm = m[2] ? `${String(m[1]).padStart(2,'0')}:${m[2]}` : `${String(m[1]).padStart(2,'0')}:00`;
}
if (!bulk && cands.length > 1 && hm) { const f = cands.filter(a => when(a).toFormat('HH:mm') === hm); if (f.length) cands = f; }

// 4) ordinal / número sobre la lista actual (en el mismo orden en que se le mostró) -- nunca si es bulk
if (!bulk && cands.length > 1) {
  const ORD = { primera: 1, uno: 1, segunda: 2, dos: 2, tercera: 3, tres: 3, cuarta: 4, cuatro: 4 };
  let pick = null;
  const numMatch = msg.match(/\b(?:la\s+)?(?:numero\s+)?([1-9])\b/);
  if (numMatch) pick = Number(numMatch[1]);
  if (!pick) for (const [k, i] of Object.entries(ORD)) if (msg.includes(k)) { pick = i; break; }
  if (/\bultim[ao]\b/.test(msg)) pick = cands.length;
  if (pick && cands[pick - 1]) cands = [cands[pick - 1]];
}

// Si el usuario no dio NINGÚN dato que distinga (ningún filtro anterior descartó nada) y hay una
// cita 'recién tocada' en esta sesión, se asume que se refiere a esa (referencia implícita:
// "mejor pasarla al jueves" tras acabar de reservar/tocar una cita).
if (!bulk && cands.length > 1 && cands.length === appts.length && core.last_appointment_id) {
  const recent = appts.find(a => a.id === core.last_appointment_id);
  if (recent) cands = [recent];
}

if (cands.length === 1) return [{ json: { ...base, _found: true, appointment_id: cands[0].id } }];
return [{ json: { ...base, _found: false, _reason: bulk ? 'en_bloque' : 'ambigua',
  opciones: cands.map((a, i) => ({ n: i + 1, id: a.id,
    cuando: when(a).setLocale('es').toFormat("cccc d 'de' LLLL 'a las' HH:mm") })) } }];

const m = $json ?? {};
const core = $('Output IA → JSON').item.json;
const tz = core.tenant_timezone || 'Europe/Madrid';
if (!core.date) return [{ json: { ...m, _no_new_slot: true, _have_date: false } }];
if (!core.time) return [{ json: { ...m, _no_new_slot: true, _have_date: true, _new_date: core.date } }];
const s = DateTime.fromISO(`${core.date}T${core.time}`, { zone: tz });
if (!s.isValid) return [{ json: { ...m, _no_new_slot: true, _have_date: true, _new_date: core.date } }];
return [{ json: { ...m, start_at: s.toISO() } }];

const r = $json ?? {};
const tz = $('Output IA → JSON').item.json.tenant_timezone || 'Europe/Madrid';
if (r.ok === true) {
  const a = (r.data && r.data.appointment) || {};
  const cuando = a.start_at ? DateTime.fromISO(a.start_at).setZone(tz).setLocale('es').toFormat("cccc d 'de' LLLL 'a las' HH:mm") : '';
  return [{ json: { ok: true, intent: 'reschedule_appointment', needs_user_reply: false, reply_to_user: `Hecho, tu cita queda para el ${cuando}.`, appointment: a, last_appointment_id: a.id } }];
}
const st = (r.data && r.data.result && r.data.result.status) || r.status;
if (st === 'slot_conflict') return [{ json: { ok:false, intent:'reschedule_appointment', needs_user_reply:true, reply_to_user:'Ese horario no está disponible ese día. ¿Te digo los huecos libres?' } }];
if (st === 'slot_taken')   return [{ json: { ok:false, intent:'reschedule_appointment', needs_user_reply:true, reply_to_user:'Ese horario acaba de ocuparse. ¿Quieres otro?' } }];
return [{ json: { ok:false, intent:'reschedule_appointment', needs_user_reply:true, reply_to_user: r.message || 'No he podido reprogramar la cita.' } }];

const r = $json ?? {};
const pending_appointment_id = r.appointment_id || null;
if (r._have_date) {
  const dia = r._new_date
    ? DateTime.fromISO(r._new_date).setLocale('es').toFormat("cccc d 'de' LLLL")
    : 'ese día';
  return [{ json: { ok: true, intent: 'reschedule_appointment', needs_user_reply: true,
    reply_to_user: `¿A qué hora en concreto el ${dia}? (por ejemplo, "a las 10:30")`,
    pending_appointment_id } }];
}
return [{ json: { ok: true, intent: 'reschedule_appointment', needs_user_reply: true,
  reply_to_user: '¿A qué día y hora quieres moverla?', pending_appointment_id } }];

const r = $json ?? {};
if (r.ok === true) return [{ json: { ok: true, intent: 'cancel_appointment', needs_user_reply: false, reply_to_user: 'Tu cita queda cancelada.', appointment: (r.data && r.data.appointment) } }];
return [{ json: { ok: false, intent: 'cancel_appointment', needs_user_reply: true, reply_to_user: r.message || 'No he podido cancelar la cita.' } }];

const m = $json ?? {};
const accion = m.intent === 'cancel_appointment' ? 'cancelar' : 'cambiar';
const map = {
  varios_contactos: 'Necesito confirmar quién eres. ¿Me das tu teléfono?',
  sin_contacto: 'No encuentro tus datos. ¿Me dices tu nombre y teléfono?',
  sin_citas: 'No veo ninguna cita próxima a tu nombre.',
};
if (m._reason === 'ambigua' || m._reason === 'en_bloque') {
  const lista = (m.opciones || []).map(o => `${o.n}) ${o.cuando}`).join('   ');
  const prefijo = m._reason === 'en_bloque' ? 'De momento solo puedo gestionar una cita cada vez. ' : '';
  return [{ json: { ok: false, intent: m.intent, needs_user_reply: true,
    reply_to_user: `${prefijo}Tienes varias citas próximas: ${lista}. ¿Cuál quieres ${accion}? Dime el día o el número.` } }];
}
return [{ json: { ok: false, intent: m.intent, needs_user_reply: true,
  reply_to_user: map[m._reason] || 'No he podido localizar la cita.' } }];

const r = $json ?? {};
const code = r.statusCode ?? 0;
const body = (r.body ?? r) || {};
if (code >= 300 || (body && body.errors)) {
  throw new Error('Directus /items/knowledge devolvió ' + code + ': ' + JSON.stringify(body.errors || body));
}
const rows = Array.isArray(body.data) ? body.data : [];
const kb = rows.map(x => `## ${x.title}\n${(x.body || '').trim()}`).join('\n\n').trim();
return [{ json: {
  message: $('Output IA → JSON').item.json.message,
  kb: kb || '(este negocio todavía no tiene información en su base de conocimiento)',
} }];

// Estructura viene del outcome determinista; la prosa la pone el Redactor (si falla, borrador).
const s = $('Código · outcome').item.json ?? {};
const io = $('Output IA → JSON').item.json ?? {};
const prose = ($json && $json.output ? $json.output : '').toString().trim();
const ok = s.ok !== false;
const intent = (s.intent === undefined || s.intent === 'null') ? null : (s.intent ?? null);
const needs = s.needs_user_reply === true;
const flujo_activo = (!needs || !intent) ? null : intent;
const taskObj = (s.task && s.task.task) ? s.task.task : (s.task || null);
const contact_id = s.contact_id
  ?? (s.appointment && s.appointment.contact_id)
  ?? (taskObj && taskObj.contact_id)
  ?? null;
const contact_phone = s.contact_phone
  ?? (io.contact && io.contact.phone)
  ?? null;
const pending_appointment_id = s.pending_appointment_id ?? null;
const last_appointment_id = s.last_appointment_id ?? null;
const awaiting_slots_offer = s.awaiting_slots_offer === true;
const alt_slots_date = s.alt_slots_date ?? null;
const alt_slots_time = s.alt_slots_time ?? null;
const result = s.appointment ?? taskObj ?? s.result ?? null;
return [{ json: {
  ok, intent,
  reply_to_user: prose || s.reply_to_user || '',
  needs_user_reply: needs, flujo_activo, contact_id, contact_phone, pending_appointment_id, last_appointment_id,
  awaiting_slots_offer, alt_slots_date, alt_slots_time, result,
} }];

const core = $('Output IA → JSON').item.json;
const res = $json ?? {};
const tz = core.tenant_timezone || 'Europe/Madrid';
if (!res.ok) {
  const reason = res.status === 'multiple' ? 'Necesito confirmar quién eres. ¿Me das tu teléfono?'
    : 'No encuentro tus datos. ¿Me dices tu nombre y teléfono?';
  return [{ json: { ok: false, intent: 'my_appointments', needs_user_reply: true, reply_to_user: reason } }];
}
const appts = Array.isArray(res.data && res.data.appointments) ? res.data.appointments : [];
if (!appts.length) {
  return [{ json: { ok: true, intent: 'my_appointments', needs_user_reply: false,
    reply_to_user: 'No tienes ninguna cita próxima.' } }];
}
const fmt = a => DateTime.fromISO(a.start_at).setZone(tz).setLocale('es').toFormat("cccc d 'de' LLLL 'a las' HH:mm");
let reply;
if (appts.length === 1) {
  reply = `Tu única cita próxima es el ${fmt(appts[0])}.`;
} else {
  reply = `Tienes ${appts.length} citas próximas: ` + appts.map(fmt).join('; ') + '.';
}
return [{ json: { ok: true, intent: 'my_appointments', needs_user_reply: false, reply_to_user: reply,
  result: { count: appts.length } } }];

const s = $json ?? {};
// Ya redactado (list_availability tiene su propio agente), o resultado TERMINAL
// (operación ya ejecutada: reserva/cancelación/reprogramación confirmada, tarea anotada,
// conocimiento respondido...): el texto determinista es la fuente de verdad, no se retoca.
const skip_redactor = s._already_styled === true || (s.ok !== false && s.needs_user_reply === false);
return [{ json: { ...s, reply_to_user: (s.reply_to_user || '').toString(), skip_redactor } }];

const core = $('Output IA → JSON').item.json;
const phone = core.contact && core.contact.phone ? core.contact.phone : null;
const query = core.contact && core.contact.name ? core.contact.name : null;
return [{ json: { intent: core.intent, phone, query, _found: true,
  appointment_id: core.pending_appointment_id } }];
